n    // Can't be self\n    require!(!referrer.eq(&player), CustomErrors::InvalidReferrer);\n\n    // Returns (ref_fee, cashback)\n    let ref_fee;\n    let cashback;\n\n    // Proceed with referral\n    player_state.current_referrer = referrer;\n\n    // Calculate referral fee and cashback\n    ref_fee = amount\n        .checked_mul(REFERRAL_FEE)\n        .unwrap_or_default()\n        .checked_div(100)\n        .unwrap_or_default();\n    cashback = amount\n        .checked_mul(REFERRAL_CASHBACK)\n        .unwrap_or_default()\n        .checked_div(100)\n        .unwrap_or_default();\n\n    // Update referrer's total with their fee\n    referrer_state.referral_total = referrer_state.referral_total.checked_add(ref_fee).unwrap();\n\n    // Update buyer's referral total with their cashback\n    player_state.referral_total = player_state.referral_total.checked_add(cashback).unwrap();\n\n    // Add both ref fee and cashback to sell_and_ref_balance for tracking\n    game_state.sell_and_ref_balance = game_state\n        .sell_and_ref_balance\n        .checked_add(ref_fee)\n        .unwrap()\n        .checked_add(cashback)\n        .unwrap();\n\n    Ok((ref_fee, cashback))\n}\n"})})]})]})}function u(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},8453:(e,r,a)=>{a.d(r,{R:()=>c,x:()=>l});var n=a(6540);const t={},s=n.createContext(t);function c(e){const r=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:c(e.components),n.createElement(s.Provider,{value:r},e.children)}}}]);